function iterativeQuicksort(a){
  const n=a.length;
  const stack=[[0,n-1]];
  const swap=(i,j)=>{let t=a[i]; a[i]=a[j]; a[j]=t;};
  while(stack.length){
    const [l,r]=stack.pop();
    if(l>=r) continue;
    let pivot=a[(l+r)>>1];
    let i=l, j=r;
    while(i<=j){
      while(a[i]<pivot) i++;
      while(a[j]>pivot) j--;
      if(i<=j){ swap(i,j); i++; j--; }
    }
    if(l<j) stack.push([l,j]);
    if(i<r) stack.push([i,r]);
  }
  return a;
}
```

